from identity_client import IdentityClient
from identity_models import TranslateRequest, TranslateResponse

def welcome_translate(request: TranslateRequest) -> TranslateResponse:
    client = IdentityClient()

    if not client.google_translation_client:
        raise ValueError("Google Cloud Translation client not configured.")

    try:
        result = client.google_translation_client.translate(
            request.text, target_language=request.target_language, source_language=request.source_language
        )

        translated_text = result["translatedText"]
        return TranslateResponse(translated_text=translated_text)
    except Exception as e:
        raise RuntimeError(f"Google Cloud Translation failed: {e}")

from identity_client import IdentityClient
from identity_models import SummarizeRequest, SummarizeResponse

def onboarding_summary(request: SummarizeRequest) -> SummarizeResponse:
    client = IdentityClient()

    if not client.aws_comprehend_client:
        raise ValueError("AWS Comprehend client not configured.")

    try:
        # AWS Comprehend doesn't have a direct 'summarize' API.
        # We will use 'detect_key_phrases' as a way to extract salient information
        # that can be used to construct a summary or provide key insights.
        response = client.aws_comprehend_client.detect_key_phrases(
            Text=request.text,
            LanguageCode="en" # Assuming onboarding text is in English
        )

        key_phrases = [phrase["Text"] for phrase in response["KeyPhrases"]]
        summary_text = "; ".join(key_phrases)

        if not summary_text:
            summary_text = "No key phrases detected for summarization."

        return SummarizeResponse(summary=summary_text)
    except Exception as e:
        raise RuntimeError(f"AWS Comprehend summarization failed: {e}")

import uuid
import datetime
from identity_client import IdentityClient
from identity_models import ProfileNote, StoreNoteResponse

def profile_note_store(note: ProfileNote) -> StoreNoteResponse:
    client = IdentityClient()

    if not client.mongodb_collection:
        raise ValueError("MongoDB Atlas client not configured.")

    try:
        # Add a unique ID and timestamp if not already present
        if not hasattr(note, "note_id") or not note.note_id:
            note.note_id = str(uuid.uuid4())
        if not note.timestamp:
            note.timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()

        # Convert dataclass to dictionary for MongoDB insertion
        note_dict = {k: v for k, v in note.__dict__.items() if v is not None}

        result = client.mongodb_collection.insert_one(note_dict)

        return StoreNoteResponse(note_id=str(result.inserted_id), message="Profile note stored successfully.")
    except Exception as e:
        raise RuntimeError(f"MongoDB Atlas note storage failed: {e}")
